import React, { useState, useRef } from 'react';
import { View, Text, TouchableOpacity, Dimensions, TextInput } from 'react-native';

import { useContexState } from '../../../hooks/context';
import { styles } from './styles';

import api from '../../../services/api';

import { Entypo } from '@expo/vector-icons';

export function RegisterMenu() {
    const [value, onChangeText] = useState('Buscar');

    const ref = useRef<TextInput>(null);
    const [LoadAddCart, setLoadAddCart] = useState(false);

    const {
        shoppingCartItem,
        selectedNumber,
        paymentMenuActive
    } = useContexState();

    const {
        setShoppingCartItem,
        setPaymentMenuActive
    } = useContexState();


    function filterString(text: string) {
        if (text === text.replace(/[^0-9]/g, '')) onChangeText(text);
    };


    function Input() {
        return (
            <TextInput
                style={styles.input}
                onChangeText={text => {/*filterString(text)*/ }}
                //  value={value}
                maxLength={4}
                keyboardType={'numeric'}
                autoCorrect={false}
                placeholderTextColor='#fff'
                onFocus={() => {
                    ref.current?.clear();
                    onChangeText('');
                }}
                ref={ref}
            />

        )
    }





    function Menu() {


        return (
            <>
                <View style={{
                    backgroundColor: '#26A744', borderRadius: 15, width: 230, padding: 10,
                }} >
                    <Text style={{ color: '#fff', fontSize: 30}}>Comprar agora</Text>
                    <Input />
                </View>

                <TouchableOpacity onPress={() => { }} style={{ backgroundColor: '#17A2B7', borderRadius: 15, width: 230, padding: 10, margin: 10 }} >
                    <Text style={{ color: '#fff', fontSize: 30, textAlign: 'center' }}>Adicionar ao {'\n'}carrinho</Text>
                </TouchableOpacity>

                <TouchableOpacity style={{
                    backgroundColor: '#DAA520', borderRadius: 15, width: 230, padding: 10,
                }} >
                    <Text style={{ color: '#fff', fontSize: 30, textAlign: 'center' }}>Revender</Text>
                    <Text style={{ color: '#fff', fontSize: 16, textAlign: 'center' }}>Apenas para representantes!</Text>
                </TouchableOpacity>
            </>
        );
    }


    return (
        true ?
            <>
                <TouchableOpacity onPress={() => {
                    setPaymentMenuActive(false);
                }} style={{
                    position: 'absolute',
                    alignItems: 'center',
                    justifyContent: 'center',
                    minWidth: Dimensions.get('window').width,
                    minHeight: Dimensions.get('window').height
                }} />

                <View style={styles.container} >
                    <Menu />
                </View>
            </> : null
    );
};
